window.DATA_PART_F=window.DATA_PART_F||{};window.DATA_PART_F["bsk"]={"formulas":{"bsk-f118":{"svg":"<svg viewBox=\"0 0 300 206\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"Frenkel-Modell: Schubspannung als Sinus über der Verschiebung, Periode b, Maximum tau th\"><line x1=\"46\" y1=\"170\" x2=\"46\" y2=\"22\" stroke=\"currentColor\" stroke-width=\"1.3\"/><polygon points=\"46,14 42,22 50,22\" fill=\"currentColor\"/><line x1=\"46\" y1=\"95\" x2=\"270\" y2=\"95\" stroke=\"currentColor\" stroke-width=\"1.3\"/><polygon points=\"280,95 272,91 272,99\" fill=\"currentColor\"/><text x=\"52\" y=\"22\" font-size=\"13\" fill=\"currentColor\" text-anchor=\"start\" font-weight=\"700\">τ</text><text x=\"288\" y=\"113\" font-size=\"13\" fill=\"currentColor\" text-anchor=\"end\" font-weight=\"700\">δ</text><polyline id=\"f118-curve\" class=\"an\" points=\"46,95 49.3,89.3 52.7,83.6 56,78 59.3,72.6 62.7,67.5 66,62.7 69.3,58.2 72.7,54.1 76,50.5 79.3,47.4 82.7,44.8 86,42.7 89.3,41.2 92.7,40.3 96,40 99.3,40.3 102.7,41.2 106,42.7 109.3,44.8 112.7,47.4 116,50.5 119.3,54.1 122.7,58.2 126,62.7 129.3,67.5 132.7,72.6 136,78 139.3,83.6 142.7,89.3 146,95 149.3,100.7 152.7,106.4 156,112 159.3,117.4 162.7,122.5 166,127.3 169.3,131.8 172.7,135.9 176,139.5 179.3,142.6 182.7,145.2 186,147.3 189.3,148.8 192.7,149.7 196,150 199.3,149.7 202.7,148.8 206,147.3 209.3,145.2 212.7,142.6 216,139.5 219.3,135.9 222.7,131.8 226,127.3 229.3,122.5 232.7,117.4 236,112 239.3,106.4 242.7,100.7 246,95\" fill=\"none\" stroke=\"var(--acc)\" stroke-width=\"2.6\"/><g id=\"f118-th\" class=\"an\"><line x1=\"46\" y1=\"40\" x2=\"96\" y2=\"40\" stroke=\"currentColor\" stroke-width=\"1.4\" stroke-dasharray=\"4 3\"/><text x=\"41\" y=\"44\" font-size=\"13\" fill=\"currentColor\" text-anchor=\"end\" font-weight=\"700\">τ<tspan font-size=\"11\" dy=\"3\">th</tspan></text></g><g id=\"f118-d\" class=\"an\"><line x1=\"71\" y1=\"95\" x2=\"71\" y2=\"56.1\" stroke=\"currentColor\" stroke-width=\"1.4\" stroke-dasharray=\"3 3\"/><circle cx=\"71\" cy=\"56.1\" r=\"3.5\" fill=\"currentColor\" stroke=\"currentColor\" stroke-width=\"1\"/><line x1=\"46\" y1=\"105\" x2=\"71\" y2=\"105\" stroke=\"currentColor\" stroke-width=\"1.4\"/><line x1=\"46\" y1=\"100\" x2=\"46\" y2=\"110\" stroke=\"currentColor\" stroke-width=\"1.2\"/><line x1=\"71\" y1=\"100\" x2=\"71\" y2=\"110\" stroke=\"currentColor\" stroke-width=\"1.2\"/><text x=\"58.5\" y=\"122\" font-size=\"12\" fill=\"currentColor\" text-anchor=\"middle\" font-weight=\"700\">δ</text></g><g id=\"f118-b\" class=\"an\"><line x1=\"46\" y1=\"176\" x2=\"246\" y2=\"176\" stroke=\"currentColor\" stroke-width=\"1.4\"/><line x1=\"46\" y1=\"170\" x2=\"46\" y2=\"182\" stroke=\"currentColor\" stroke-width=\"1.2\"/><line x1=\"246\" y1=\"170\" x2=\"246\" y2=\"182\" stroke=\"currentColor\" stroke-width=\"1.2\"/><text x=\"146\" y=\"190\" font-size=\"11\" fill=\"currentColor\" text-anchor=\"middle\">b: Ebene passt wieder</text></g><text x=\"150\" y=\"89\" font-size=\"11\" fill=\"currentColor\" text-anchor=\"start\">b/2</text></svg>","steps":[{"t":"Gegeben: \\(b = 0{,}25\\) nm, \\(\\tau_{th} = 10\\,000\\) N/mm². Gesucht ist τ bei \\(\\delta = b/12\\).","f":"\\tau = 10\\,000\\cdot\\sin\\!\\left(\\frac{2\\pi\\cdot b/12}{b}\\right) = 10\\,000\\cdot\\sin\\frac{\\pi}{6}","why":"b kürzt sich heraus: Es zählt nur, welcher Bruchteil von b geschafft ist."},{"t":"Sinus im Bogenmaß: \\(\\sin(\\pi/6) = 0{,}5\\).","f":"\\tau = 10\\,000\\cdot0{,}5 = 5000\\ \\text{N/mm}^2","why":"π/6 im Bogenmaß sind 30°."},{"t":"Bei \\(\\delta = b/4\\) ist der Winkel π/2:","f":"\\tau = 10\\,000\\cdot\\sin\\frac{\\pi}{2} = 10\\,000\\ \\text{N/mm}^2 = \\tau_{th}","why":"Hier liegt der Gipfel. Wer ihn schafft, gleitet bis zur nächsten passenden Lage."},{"t":"Bei \\(\\delta = b/2\\):","f":"\\tau = 10\\,000\\cdot\\sin\\pi = 0","why":"Die Ebene liegt genau auf dem Höcker. Ab hier zieht das Gitter sie von selbst weiter."}],"mistakes":["✗ Rechner im Grad-Modus: \\(\\sin(\\pi/6)\\) als Grad gibt 0,009. ✓ Im Bogenmaß rechnen oder π/6 = 30° einsetzen.","✗ Den Gipfel bei \\(\\delta = b/2\\) suchen. ✓ Er liegt bei \\(b/4\\); bei \\(b/2\\) ist τ null.","✗ \\(\\tau_{th}\\) für die echte Festigkeit halten. ✓ Echte Metalle gleiten viel früher, weil Versetzungen wandern."],"why":"Stell dir zwei Eierkartons aufeinander vor. Um den oberen zu verschieben, musst du ihn erst über die Höcker heben; nach einem Höckerabstand b passt er wieder. So beschreibt das Frenkel-Modell zwei Atomebenen. Damit schätzt du, wie fest ein Kristall ohne Fehler wäre, und siehst, warum echte Metalle viel weicher sind."},"bsk-f119":{"steps":[{"t":"Für kleine δ gilt \\(\\sin x\\approx x\\):","f":"\\tau\\approx\\tau_{th}\\cdot\\frac{2\\pi\\,\\delta}{b}","why":"Nahe null ist die Sinuskurve fast eine Gerade."},{"t":"Hooke für Schub mit dem Gleitwinkel \\(\\gamma = \\delta/h\\):","f":"\\tau = G\\cdot\\frac{\\delta}{h}","why":"Die obere Ebene verschiebt sich um δ, die Ebenen liegen h auseinander."},{"t":"Gleichsetzen und nach τ_th auflösen:","f":"\\tau_{th} = \\frac{G\\cdot b}{2\\pi\\cdot h}\\approx\\frac{G}{2\\pi}","why":"δ kürzt sich heraus, und Atomabstand b und Ebenenabstand h sind etwa gleich."},{"t":"Zahlen für Aluminium: \\(E = 72\\,000\\) N/mm², \\(\\mu = 0{,}34\\).","f":"G = \\frac{72\\,000}{2\\cdot1{,}34}\\approx 26\\,870\\ \\text{N/mm}^2","why":"Erst den Schubmodul aus E und μ (Vorlesung 2)."},{"t":"Theoretische Schubfestigkeit:","f":"\\tau_{th}\\approx\\frac{26\\,870}{2\\pi}\\approx 4280\\ \\text{N/mm}^2","why":"Das ist ein Vielfaches dessen, was Aluminium real aushält (laut Umdruck 50 bis 250 N/mm² Festigkeit)."}],"mistakes":["✗ E statt G einsetzen: Ergebnis rund 2,7-mal zu groß. ✓ Erst \\(G = E/(2(1+\\mu))\\) rechnen.","✗ Durch π statt durch 2π teilen. ✓ Eine Sinusperiode ist 2π.","✗ τ_th als Bemessungswert nehmen. ✓ Es ist eine obere Schranke für den perfekten Kristall."],"why":"Für kleine Verschiebungen ist die Sinuskurve fast eine Gerade, und dort gilt Hooke für Schub: τ = G·γ mit γ = δ/h. Setzt du beides gleich, bekommst du diese Formel. Sie zeigt: Ein perfekter Kristall wäre etwa G/6 fest. Echte Metalle sind viel weicher, und genau das zeigt, dass es Versetzungen gibt."},"bsk-f120":{"svg":"<svg viewBox=\"0 0 270 210\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"KRZ-Elementarzelle: Raumdiagonale a mal Wurzel 3 gleich 4 r, zwei Atome je Zelle\"><line x1=\"74\" y1=\"136\" x2=\"74\" y2=\"46\" stroke=\"currentColor\" stroke-width=\"1\" stroke-dasharray=\"3 3\"/><line x1=\"74\" y1=\"136\" x2=\"164\" y2=\"136\" stroke=\"currentColor\" stroke-width=\"1\" stroke-dasharray=\"3 3\"/><line x1=\"74\" y1=\"136\" x2=\"34\" y2=\"166\" stroke=\"currentColor\" stroke-width=\"1\" stroke-dasharray=\"3 3\"/><line x1=\"34\" y1=\"76\" x2=\"124\" y2=\"76\" stroke=\"currentColor\" stroke-width=\"1.2\"/><line x1=\"124\" y1=\"76\" x2=\"124\" y2=\"166\" stroke=\"currentColor\" stroke-width=\"1.2\"/><line x1=\"124\" y1=\"166\" x2=\"34\" y2=\"166\" stroke=\"currentColor\" stroke-width=\"1.2\"/><line x1=\"34\" y1=\"166\" x2=\"34\" y2=\"76\" stroke=\"currentColor\" stroke-width=\"1.2\"/><line x1=\"74\" y1=\"46\" x2=\"164\" y2=\"46\" stroke=\"currentColor\" stroke-width=\"1.2\"/><line x1=\"164\" y1=\"46\" x2=\"164\" y2=\"136\" stroke=\"currentColor\" stroke-width=\"1.2\"/><line x1=\"34\" y1=\"76\" x2=\"74\" y2=\"46\" stroke=\"currentColor\" stroke-width=\"1.2\"/><line x1=\"124\" y1=\"76\" x2=\"164\" y2=\"46\" stroke=\"currentColor\" stroke-width=\"1.2\"/><line x1=\"124\" y1=\"166\" x2=\"164\" y2=\"136\" stroke=\"currentColor\" stroke-width=\"1.2\"/><g id=\"f120-r\" class=\"an\"><line x1=\"34\" y1=\"166\" x2=\"164\" y2=\"46\" stroke=\"var(--acc)\" stroke-width=\"2.4\"/><text x=\"172\" y=\"102\" font-size=\"12\" fill=\"currentColor\" text-anchor=\"start\" font-weight=\"700\">a·√3 = 4r</text></g><g id=\"f120-a\" class=\"an\"><line x1=\"34\" y1=\"178\" x2=\"124\" y2=\"178\" stroke=\"currentColor\" stroke-width=\"1.4\"/><line x1=\"34\" y1=\"172\" x2=\"34\" y2=\"184\" stroke=\"currentColor\" stroke-width=\"1.2\"/><line x1=\"124\" y1=\"172\" x2=\"124\" y2=\"184\" stroke=\"currentColor\" stroke-width=\"1.2\"/><text x=\"79\" y=\"194\" font-size=\"12\" fill=\"currentColor\" text-anchor=\"middle\" font-weight=\"700\">a</text></g><g id=\"f120-N\" class=\"an\"><circle cx=\"74\" cy=\"46\" r=\"7\" fill=\"var(--acc)\" stroke=\"currentColor\" stroke-width=\"1\"/><circle cx=\"164\" cy=\"46\" r=\"7\" fill=\"var(--acc)\" stroke=\"currentColor\" stroke-width=\"1\"/><circle cx=\"164\" cy=\"136\" r=\"7\" fill=\"var(--acc)\" stroke=\"currentColor\" stroke-width=\"1\"/><circle cx=\"74\" cy=\"136\" r=\"7\" fill=\"var(--acc)\" stroke=\"currentColor\" stroke-width=\"1\"/><circle cx=\"34\" cy=\"76\" r=\"7\" fill=\"var(--acc)\" stroke=\"currentColor\" stroke-width=\"1\"/><circle cx=\"124\" cy=\"76\" r=\"7\" fill=\"var(--acc)\" stroke=\"currentColor\" stroke-width=\"1\"/><circle cx=\"124\" cy=\"166\" r=\"7\" fill=\"var(--acc)\" stroke=\"currentColor\" stroke-width=\"1\"/><circle cx=\"34\" cy=\"166\" r=\"7\" fill=\"var(--acc)\" stroke=\"currentColor\" stroke-width=\"1\"/><circle cx=\"99\" cy=\"106\" r=\"7\" fill=\"var(--acc)\" stroke=\"currentColor\" stroke-width=\"1\"/></g><text x=\"12\" y=\"22\" font-size=\"12\" fill=\"currentColor\" text-anchor=\"start\">N = 8 · ⅛ + 1 = 2</text></svg>","steps":[{"t":"Atome je KRZ-Zelle: 8 Ecken zu je \\(\\tfrac18\\) und 1 in der Mitte.","f":"N = 8\\cdot\\tfrac18 + 1 = 2","why":"Jede Ecke gehört zu 8 Würfeln, das Mittelatom nur zu diesem."},{"t":"Die Kugeln berühren sich auf der Raumdiagonalen:","f":"a\\sqrt3 = 4r\\quad\\Rightarrow\\quad a = \\frac{4r}{\\sqrt3}\\approx 2{,}309\\,r","why":"Auf der Diagonalen liegen ein halbes Eckatom, das ganze Mittelatom und noch ein halbes Eckatom: zusammen 4 Radien."},{"t":"Einsetzen:","f":"\\eta = \\frac{2\\cdot\\frac43\\pi r^3}{(4r/\\sqrt3)^3} = \\frac{8{,}378\\,r^3}{12{,}32\\,r^3}","why":"\\(r^3\\) steht oben und unten."},{"t":"Ergebnis:","f":"\\eta = \\frac{\\pi\\sqrt3}{8}\\approx 0{,}68 = 68\\,\\%","why":"Gilt für jedes KRZ-Metall, egal wie groß seine Atome sind."}],"mistakes":["✗ Jedes Eckatom voll zählen (KRZ: N = 9). ✓ Eine Ecke gehört zu 8 Würfeln und zählt \\(\\tfrac18\\).","✗ \\(a = 2r\\) setzen. ✓ Das gilt nur für KP. Bei KRZ berühren sich die Kugeln auf der Raumdiagonalen (\\(a\\sqrt3 = 4r\\)), bei KFZ auf der Flächendiagonalen (\\(a\\sqrt2 = 4r\\)).","✗ Ein Ergebnis über 1. ✓ η ist ein Anteil; mit gleich großen Kugeln geht nicht mehr als 74 %."],"why":"Die Folie nennt 52, 68 und 74 %. Mit dieser Formel siehst du, woher die Zahlen kommen (Ergänzung zur Folie). Dicht gepackte Gitter haben viele Nachbarn und viele Gleitsysteme; KFZ-Metalle wie Kupfer und Aluminium sind darum gut verformbar."},"bsk-f121":{"steps":[{"t":"KFZ (Kupfer): 4 Ebenen, je 3 Richtungen.","f":"n_{GS} = 4\\cdot3 = 12","why":"Jede der 3 Richtungen liegt in jeder der 4 Ebenen."},{"t":"HDP (Zink), Basisebene: 1 Ebene, 3 Richtungen.","f":"n_{GS} = 1\\cdot3 = 3","why":"Nur die Basisebene ist dicht gepackt."},{"t":"Vergleich:","f":"12 : 3 = 4","why":"Kupfer hat viermal so viele Möglichkeiten zu gleiten."}],"mistakes":["✗ Ebenen und Richtungen addieren (4 + 3 = 7). ✓ Malnehmen.","✗ Gleitebenen und Gleitsysteme verwechseln. ✓ KFZ hat 4 Ebenen, aber 12 Systeme."],"why":"Ein Korn kann nur gleiten, wenn eines seiner Gleitsysteme günstig zur Last liegt. Je mehr Systeme, desto eher klappt das in jedem Korn und desto duktiler ist das Metall. Darum ist Kupfer (KFZ, 12) gut verformbar und Zink (HDP, 3) spröder."},"bsk-f122":{"steps":[{"t":"Warum gerade die Steigung? Spannung und Dehnung im Atommaßstab (Ergänzung):","f":"\\sigma\\approx\\frac{\\Delta F}{a_0^2},\\qquad \\varepsilon=\\frac{\\Delta a}{a_0}","why":"Auf ein Atom entfällt etwa die Fläche \\(a_0^2\\), gedehnt wird um Δa bezogen auf \\(a_0\\)."},{"t":"Teilen:","f":"E=\\frac{\\sigma}{\\varepsilon}\\approx\\frac{1}{a_0}\\cdot\\frac{\\Delta F}{\\Delta a}","why":"Bei ähnlichem \\(a_0\\) entscheidet nur die Steigung."},{"t":"Zahlen: Die Kurve von Stoff A ist in \\(a_0\\) 70-mal so steil wie bei Plexiglas (\\(E = 3000\\) N/mm²), \\(a_0\\) ist gleich.","f":"E_A\\approx70\\cdot3000 = 210\\,000\\ \\text{N/mm}^2","why":"Das ist der Wert von Stahl: Metallbindung statt Van-der-Waals-Kräfte zwischen Ketten."}],"mistakes":["✗ Die Steigung weit weg von \\(a_0\\) ablesen. ✓ Bauteile dehnen sich nur um Promille, also zählt nur die Steigung in der Ruhelage.","✗ Steif mit fest verwechseln. ✓ E sagt, wie stark sich ein Stoff verformt, nicht wann er bricht; Glasfasern haben E = 70 000 N/mm² und sind trotzdem spröde."],"why":"Ziehst du an einem Bauteil, ziehst du an unzähligen Bindungen. Wie stark eine Bindung dagegenhält, zeigt die Steigung der Kraft-Abstands-Kurve in der Ruhelage. Steile Kurve: steifer Stoff (Keramik, Metall). Flache Kurve: weicher Stoff (Kunststoff mit Van-der-Waals-Bindungen, Gele)."},"bsk-f123":{"steps":[{"t":"Stahl, \\(\\alpha_T = 12\\cdot10^{-6}\\) 1/K, 30 K wärmer:","f":"\\varepsilon_T = 12\\cdot10^{-6}\\cdot30 = 0{,}00036 = 0{,}36\\ \\text{‰}","why":"Mal 1000 ergibt Promille."},{"t":"Für einen 6 m langen Träger:","f":"\\Delta l_T = 0{,}00036\\cdot6000\\ \\text{mm} = 2{,}16\\ \\text{mm}","why":"Dehnung mal Länge in mm ergibt mm."}],"mistakes":["✗ 0,00036 als 0,36 % lesen. ✓ Mal 1000 ergibt 0,36 ‰ (= 0,036 %).","✗ 273 zu ΔT addieren. ✓ Eine Temperaturdifferenz ist in K und in °C gleich groß."],"why":"Das ist die Wärmedehnung aus Vorlesung 2, nur als Dehnung statt als Länge. So kannst du sie direkt zur Dehnung aus der Last addieren oder mit E in eine Zwangsspannung umrechnen."},"bsk-f124":{"steps":[{"t":"Freie Wärmedehnung, Stahlträger, 25 K wärmer:","f":"\\varepsilon_T = 12\\cdot10^{-6}\\cdot25 = 0{,}0003 = 0{,}3\\ \\text{‰}","why":"So viel länger würde der Träger, wenn er dürfte."},{"t":"Die Wände drücken ihn um genau diese Dehnung zurück:","f":"\\varepsilon_{Last} = -0{,}0003","why":"Die Gesamtdehnung muss null bleiben."},{"t":"Hooke:","f":"\\sigma_T = 210\\,000\\cdot(-0{,}0003) = -63\\ \\text{N/mm}^2","why":"Minus heißt Druck. Die Länge des Trägers kommt gar nicht vor."}],"mistakes":["✗ Die Länge einsetzen. ✓ Die Spannung hängt nicht von der Länge ab, weil die Dehnung schon auf die Länge bezogen ist.","✗ Vorzeichen vergessen. ✓ Erwärmung behindert → Druck (minus); Abkühlung behindert → Zug (plus).","✗ Die Formel bei frei verschieblichem Bauteil anwenden. ✓ Kann es sich ausdehnen, entsteht keine Spannung, nur eine Längenänderung."],"why":"Ein Stahlträger klemmt zwischen zwei massiven Wänden. Wird er warm, will er länger werden, darf aber nicht. Die Wände drücken ihn genau um die Wärmedehnung zurück. Diese Spannung entsteht ganz ohne äußere Last und kann Lager, Fugen oder das Bauteil selbst schädigen."},"bsk-f125":{"steps":[{"t":"Zugstange: \\(F = 200\\) kN, \\(f_t = 400\\) N/mm².","f":"A_{erf} = \\frac{200\\,000\\ \\text{N}}{400\\ \\text{N/mm}^2} = 500\\ \\text{mm}^2","why":"kN erst in N umrechnen, dann kürzen sich die Newton."},{"t":"Mit Sicherheitsfaktor 2 halbierst du erst die Festigkeit:","f":"A_{erf} = \\frac{200\\,000}{400/2} = 1000\\ \\text{mm}^2","why":"Die zulässige Spannung ist kleiner als die Festigkeit."}],"mistakes":["✗ kN einsetzen: 0,5 mm² statt 500 mm². ✓ Erst in N umrechnen.","✗ Das Ergebnis abrunden. ✓ Es ist ein Mindestwert: immer aufrunden."],"why":"Du drehst σ = F/A um: Statt die Spannung zu prüfen, suchst du die Fläche, bei der die Spannung genau die Festigkeit erreicht. So bemisst du Zugstangen, Seile oder Stützen. In der Praxis teilst du die Festigkeit vorher noch durch einen Sicherheitsfaktor."},"bsk-f126":{"steps":[{"t":"Fläche 500 mm²:","f":"\\frac{500}{\\pi}\\approx159{,}15\\ \\text{mm}^2","why":"Erst durch π teilen."},{"t":"Wurzel und mal 2:","f":"d = 2\\cdot\\sqrt{159{,}15}\\approx2\\cdot12{,}62 = 25{,}23\\ \\text{mm}","why":"Die Wurzel gibt den Radius, mal 2 den Durchmesser."},{"t":"Aufrunden:","f":"d = 26\\ \\text{mm}","why":"Die Fläche darf nicht kleiner werden."}],"mistakes":["✗ Faktor 2 vergessen: Das ist der Radius (12,6 mm). ✓ d = 2r.","✗ Die Wurzel vergessen. ✓ Die Fläche wächst mit d², also zurück mit der Wurzel."],"why":"Aus der erforderlichen Fläche willst du einen Rundstab wählen. Dafür stellst du \\(A = \\pi d^2/4\\) nach d um."},"bsk-f127":{"steps":[{"t":"Stahlstab, Zug \\(\\sigma = +120\\) N/mm², \\(E = 210\\,000\\) N/mm²:","f":"\\frac{\\sigma}{E} = \\frac{120}{210\\,000}\\approx +0{,}000571","why":"Zug verlängert: plus."},{"t":"Gleichzeitig 20 K Abkühlung, \\(\\alpha_T = 12\\cdot10^{-6}\\) 1/K:","f":"\\alpha_T\\cdot\\Delta T = 12\\cdot10^{-6}\\cdot(-20) = -0{,}00024","why":"Abkühlung verkürzt: minus."},{"t":"Summe mal \\(l_0 = 5\\) m \\(= 5000\\) mm:","f":"\\Delta l = (0{,}000571 - 0{,}00024)\\cdot5000\\approx +1{,}66\\ \\text{mm}","why":"Erst mit Vorzeichen addieren, dann mit der Länge in mm malnehmen."}],"mistakes":["✗ Beträge addieren, obwohl die Vorzeichen verschieden sind. ✓ Druck und Abkühlung minus, Zug und Erwärmung plus.","✗ l₀ in m einsetzen und das Ergebnis als mm lesen. ✓ l₀ in mm, dann kommt mm heraus.","✗ Die Formel beim eingespannten Bauteil nutzen. ✓ Dort gibt es keine Längenänderung, sondern eine Zwangsspannung."],"why":"Eine Stütze wird von der Last gestaucht und von der Sonne gewärmt. Beide Dehnungen überlagern sich. Mit Vorzeichen addiert siehst du, ob sie insgesamt kürzer oder länger wird. Das brauchst du für Fugen, Anschlüsse und Lager."},"bsk-f128":{"steps":[{"t":"1 bar in N/mm²:","f":"1\\ \\text{bar} = 10^5\\ \\tfrac{\\text{N}}{\\text{m}^2} = \\frac{10^5\\ \\text{N}}{10^6\\ \\text{mm}^2} = 0{,}1\\ \\tfrac{\\text{N}}{\\text{mm}^2}","why":"1 m² sind 1000 mal 1000 = 10⁶ mm²."},{"t":"Umgekehrt:","f":"1\\ \\tfrac{\\text{N}}{\\text{mm}^2} = 10\\ \\text{bar}","why":"Kehrwert von 0,1."},{"t":"Stütze mit 13,9 N/mm²:","f":"13{,}9\\cdot10 = 139\\ \\text{bar}","why":"Einfach mal 10."}],"mistakes":["✗ 1 N/mm² = 1 bar setzen. ✓ 1 N/mm² = 1 MPa = 10 bar."],"why":"Spannung und Druck sind beide Kraft pro Fläche. In bar kannst du dir Spannungen besser vorstellen: Ein Autoreifen hat rund 2,5 bar (Schulwissen). Eine Betonstütze mit 14 N/mm² steht also unter 140 bar."}},"anims":{}};